<script>
 import {onMount} from 'svelte';import {page} from '$app/stores';import {goto} from '$app/navigation';import {getProject,listDevices,attachProjectDevice,attachProjectSite} from '$lib/api.js';import {notify} from '$lib/stores.js';import Button from '$lib/components/Button.svelte';
 let project=null,devices=[],assigned=[],sites=[];let loading=true;let selectedDevice='';let selectedSite='';let busy=false;
 async function load(){const [p,d]=await Promise.all([getProject($page.params.id),listDevices()]);if(!p.ok){notify(p.error||'Проект не найден','error');goto('/projects');return}project=p.data.project;assigned=p.data.devices||[];sites=p.data.sites||[];if(d.ok)devices=d.data.devices||[];loading=false}
 onMount(load);
 $: available=devices.filter(d=>!assigned.some(a=>a.id===d.id));
 async function addDevice(){if(!selectedDevice)return;busy=true;const r=await attachProjectDevice(project.id,Number(selectedDevice));busy=false;if(r.ok){notify('Устройство добавлено','success');selectedDevice='';await load()}else notify(r.error||'Не удалось добавить устройство','error')}
 async function addSite(){if(!selectedSite)return;const [did,sid]=selectedSite.split(':');busy=true;const r=await attachProjectSite(project.id,Number(did),sid);busy=false;if(r.ok){notify('Сайт добавлен','success');selectedSite='';await load()}else notify(r.error||'Не удалось добавить сайт','error')}
</script>
{#if loading}<div class="empty">Загрузка…</div>{:else if project}
<div class="page-header"><div><button class="back" on:click={()=>goto('/projects')}>← Projects</button><h1 class="page-title">{project.name}</h1><p class="page-desc">{project.description||project.slug}</p></div></div>
<section class="panel"><div class="section-head"><div><h2>Devices</h2><p>Устройства, входящие в проект</p></div><div class="add"><select class="input" bind:value={selectedDevice}><option value="">Выбрать устройство</option>{#each available as d}<option value={d.id}>{d.hostname||d.device_id}</option>{/each}</select><Button variant="primary" disabled={!selectedDevice||busy} on:click={addDevice}>Добавить</Button></div></div>
{#if assigned.length}<div class="resource-list">{#each assigned as d}<div class="resource"><span class="resource-icon">▣</span><span><strong>{d.hostname||d.device_id}</strong><small>{d.device_id}</small></span><span class="muted">Device #{d.id}</span></div>{/each}</div>{:else}<div class="empty compact">В проект ещё не добавлены устройства.</div>{/if}</section>
<section class="panel"><div class="section-head"><div><h2>Websites</h2><p>Сайты, сгруппированные в проекте</p></div><div class="add"><select class="input" bind:value={selectedSite}><option value="">Выбрать сайт</option>{#each devices as d}{#each d.sites||[] as site}<option value={d.id+':'+site.site_id}>{d.hostname||d.device_id} / {site.site_id}</option>{/each}{/each}</select><Button variant="primary" disabled={!selectedSite||busy} on:click={addSite}>Добавить</Button></div></div>
{#if sites.length}<div class="resource-list">{#each sites as s}<div class="resource"><span class="resource-icon">◉</span><span><strong>{s.site_id}</strong><small>{s.device_name}</small></span></div>{/each}</div>{:else}<div class="empty compact">Сайты пока не добавлены.</div>{/if}</section>
{/if}
<style>
.back{border:0;background:none;color:#a5b4fc;font-size:10px;margin-bottom:10px}.panel{background:#101727;border:1px solid #253149;border-radius:12px;padding:16px;margin-bottom:13px}.section-head{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:13px}.section-head h2{font-size:12px}.section-head p{font-size:9px;color:#64748b;margin-top:3px}.add{display:flex;gap:7px}.add select{min-width:180px}.resource-list{display:grid;gap:6px}.resource{display:flex;align-items:center;gap:10px;padding:9px;border:1px solid #253149;border-radius:8px}.resource-icon{width:27px;height:27px;display:grid;place-items:center;background:#1b2740;color:#a5b4fc;border-radius:7px}.resource span:nth-child(2){display:grid;gap:2px;flex:1}.resource strong{font-size:10px}.resource small,.muted{font-size:9px;color:#64748b}.empty.compact{padding:17px;font-size:10px}
@media(max-width:650px){.section-head{align-items:stretch;flex-direction:column}.add select{min-width:0;flex:1}}
</style>